svg.script:
//
function selectPatient(type) {
  const slider = document.getElementById('p2-toggle-slider');
  const btnAdultText = document.getElementById('p2-btn-adult-text');
  const btnElderText = document.getElementById('p2-btn-elder-text');
  const groupAdult = document.getElementById('p2-group-adult');
  const groupElder = document.getElementById('p2-group-elder');

  if (type === 'adult') {
    slider.setAttribute('x', '152');
    slider.setAttribute('fill', 'var(--c-neutral-text)');
    btnAdultText.setAttribute('fill', 'var(--bg-color)');
    btnElderText.setAttribute('fill', 'var(--ink-muted)');
    groupAdult.setAttribute('opacity', '1');
    groupElder.setAttribute('opacity', '0.45');
    updateCompartments('adult');
  } else {
    slider.setAttribute('x', '282');
    slider.setAttribute('fill', 'var(--c-cyan)');
    btnAdultText.setAttribute('fill', 'var(--ink-muted)');
    btnElderText.setAttribute('fill', 'var(--bg-color)');
    groupAdult.setAttribute('opacity', '0.45');
    groupElder.setAttribute('opacity', '1');
    updateCompartments('elder');
  }
}

function selectComposition(patient) {
  selectPatient(patient);
  // Clear specific organ highlights on click of general composition
  document.querySelectorAll('.p2-organ-shape').forEach(el => el.classList.remove('p2-glowing'));
  document.querySelectorAll('.p2-pulse-ring').forEach(el => el.setAttribute('opacity', '0'));

  if (patient === 'adult') {
    showPanelContent('adult');
  } else {
    showPanelContent('elder');
  }
}

function selectOrgan(organ) {
  // De-highlight general composition but make sure elder group is selected/active
  selectPatient('elder');

  // Reset all organ highlights
  document.querySelectorAll('.p2-organ-shape').forEach(el => el.classList.remove('p2-glowing'));
  document.querySelectorAll('.p2-pulse-ring').forEach(el => el.setAttribute('opacity', '0'));

  // Highlight the organ in both silhouettes
  if (organ === 'liver') {
    document.getElementById('p2-adult-liver').classList.add('p2-glowing');
    document.getElementById('p2-elder-liver').classList.add('p2-glowing');
    document.getElementById('p2-adult-liver-ring').setAttribute('opacity', '1');
    document.getElementById('p2-elder-liver-ring').setAttribute('opacity', '1');
    showPanelContent('liver');
  } else if (organ === 'kidney') {
    document.getElementById('p2-adult-kidney-l').classList.add('p2-glowing');
    document.getElementById('p2-adult-kidney-r').classList.add('p2-glowing');
    document.getElementById('p2-elder-kidney-l').classList.add('p2-glowing');
    document.getElementById('p2-elder-kidney-r').classList.add('p2-glowing');
    document.getElementById('p2-adult-kidney-ring').setAttribute('opacity', '1');
    document.getElementById('p2-elder-kidney-ring').setAttribute('opacity', '1');
    showPanelContent('kidney');
  }
}

function showPanelContent(state) {
  const states = ['overview', 'adult', 'elder', 'liver', 'kidney'];
  states.forEach(s => {
    const el = document.getElementById('p2-panel-' + s);
    if (el) {
      el.style.display = (s === state) ? 'inline' : 'none';
    }
  });
}

function updateCompartments(type) {
  const adultWater = document.getElementById('p2-adult-water');
  const adultMuscle = document.getElementById('p2-adult-muscle');
  const adultFat = document.getElementById('p2-adult-fat');

  const elderWater = document.getElementById('p2-elder-water');
  const elderMuscle = document.getElementById('p2-elder-muscle');
  const elderFat = document.getElementById('p2-elder-fat');

  if (type === 'adult') {
    // Reset elder compartments to baseline or slightly dimmed
    elderWater.setAttribute('opacity', '0.4');
    elderMuscle.setAttribute('opacity', '0.4');
    elderFat.setAttribute('opacity', '0.4');

    // Animate adult compartments to full
    adultWater.setAttribute('opacity', '1');
    adultMuscle.setAttribute('opacity', '1');
    adultFat.setAttribute('opacity', '1');

    adultWater.setAttribute('y', '430'); adultWater.setAttribute('height', '0');
    adultMuscle.setAttribute('y', '430'); adultMuscle.setAttribute('height', '0');
    adultFat.setAttribute('y', '430'); adultFat.setAttribute('height', '0');

    setTimeout(() => {
      adultWater.setAttribute('y', '277'); adultWater.setAttribute('height', '153');
      adultMuscle.setAttribute('y', '213'); adultMuscle.setAttribute('height', '64');
      adultFat.setAttribute('y', '175'); adultFat.setAttribute('height', '38');
    }, 50);
  } else if (type === 'elder') {
    // Reset adult compartments
    adultWater.setAttribute('opacity', '0.4');
    adultMuscle.setAttribute('opacity', '0.4');
    adultFat.setAttribute('opacity', '0.4');

    // Animate elder compartments to full
    elderWater.setAttribute('opacity', '1');
    elderMuscle.setAttribute('opacity', '1');
    elderFat.setAttribute('opacity', '1');

    elderWater.setAttribute('y', '430'); elderWater.setAttribute('height', '0');
    elderMuscle.setAttribute('y', '430'); elderMuscle.setAttribute('height', '0');
    elderFat.setAttribute('y', '430'); elderFat.setAttribute('height', '0');

    setTimeout(() => {
      elderWater.setAttribute('y', '300'); elderWater.setAttribute('height', '130');
      elderMuscle.setAttribute('y', '260'); elderMuscle.setAttribute('height', '40');
      elderFat.setAttribute('y', '165'); elderFat.setAttribute('height', '95');
    }, 50);
  }
}

// Run initialization immediately on load
selectPatient('elder');
//
